import{_ as t,a,o as r,a6 as d}from"./chunks/framework.CJDy2q7X.js";const u=JSON.parse('{"title":"Preview","description":"","frontmatter":{"outline":false,"apiType":"rest","examples":[{"id":"rest","title":"Preview","query":"curl -X GET \\"https://your-domain.com/api/admin/appearance/themes/default/sections/preview?channel=1&locale=en\\" \\\\\\n  -H \\"Authorization: Bearer <token>\\"\\n","response":"{\\n  \\"themeCode\\": \\"default\\",\\n  \\"channelId\\": 1,\\n  \\"locale\\": \\"en\\",\\n  \\"sections\\": [\\n    {\\n      \\"id\\": 3,\\n      \\"name\\": \\"Categories Collections\\",\\n      \\"type\\": \\"category_carousel\\",\\n      \\"sortOrder\\": 1,\\n      \\"status\\": true,\\n      \\"hasDraft\\": false,\\n      \\"options\\": { \\"filters\\": { \\"sort\\": \\"asc\\", \\"limit\\": \\"10\\" } }\\n    },\\n    {\\n      \\"id\\": 15,\\n      \\"name\\": \\"Summer Sale\\",\\n      \\"type\\": \\"static_content\\",\\n      \\"sortOrder\\": 2,\\n      \\"status\\": true,\\n      \\"hasDraft\\": true,\\n      \\"options\\": { \\"html\\": \\"<h2>Summer sale</h2>\\", \\"css\\": \\".sale { color: #c00; }\\" }\\n    }\\n  ]\\n}\\n"}]},"headers":[],"relativePath":"api/rest-api/admin/appearance/sections/preview.md","filePath":"api/rest-api/admin/appearance/sections/preview.md","lastUpdated":1789385991000}'),s={name:"api/rest-api/admin/appearance/sections/preview.md"};function o(n,e,i,h,c,l){return r(),a("div",null,e[0]||(e[0]=[d('<h1 id="preview" tabindex="-1">Preview <a class="header-anchor" href="#preview" aria-label="Permalink to &quot;Preview&quot;">​</a></h1><p>The sections a channel would draw if its staged edits were published: draft content replaces published content, staged status and order are applied, sections that are off are left out, and <code>footer_links</code> stays last.</p><p>A headless storefront renders this to show a merchant their unpublished work. The storefront&#39;s own <a href="/api/rest-api/shop/sections/list.html">sections endpoint</a> never returns staged content, which is why the preview lives on the admin side and needs an admin token.</p><h2 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to &quot;Endpoint&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Purpose</th></tr></thead><tbody><tr><td><code>GET</code></td><td><code>/api/admin/appearance/themes/{code}/sections/preview</code></td><td>Preview a theme with staged edits applied</td></tr></tbody></table><h2 id="path-parameters" tabindex="-1">Path parameters <a class="header-anchor" href="#path-parameters" aria-label="Permalink to &quot;Path parameters&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><code>code</code></td><td>Theme being previewed.</td></tr></tbody></table><h2 id="query-parameters" tabindex="-1">Query parameters <a class="header-anchor" href="#query-parameters" aria-label="Permalink to &quot;Query parameters&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><code>channel</code></td><td>Channel being previewed. Falls back to the current channel.</td></tr><tr><td><code>locale</code></td><td>Locale the content is read in. Must be one the channel runs; otherwise the app locale, then the channel&#39;s first locale.</td></tr></tbody></table><h2 id="response-fields" tabindex="-1">Response fields <a class="header-anchor" href="#response-fields" aria-label="Permalink to &quot;Response fields&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>themeCode</code></td><td>string</td><td>Theme that was previewed.</td></tr><tr><td><code>channelId</code></td><td>integer</td><td>Channel that was previewed.</td></tr><tr><td><code>locale</code></td><td>string</td><td>Locale the content was read in.</td></tr><tr><td><code>sections</code></td><td>array</td><td>Sections in the order they would be drawn.</td></tr><tr><td><code>sections[].id</code></td><td>integer</td><td>Section ID.</td></tr><tr><td><code>sections[].name</code></td><td>string</td><td>Section name.</td></tr><tr><td><code>sections[].type</code></td><td>string</td><td>Section type.</td></tr><tr><td><code>sections[].sortOrder</code></td><td>integer</td><td>Position, staged value applied.</td></tr><tr><td><code>sections[].status</code></td><td>boolean</td><td>On/off, staged value applied. Always <code>true</code> for returned sections.</td></tr><tr><td><code>sections[].hasDraft</code></td><td>boolean</td><td>Whether this section is holding a staged edit.</td></tr><tr><td><code>sections[].options</code></td><td>object | null</td><td>Content for the locale, staged value applied.</td></tr></tbody></table><h2 id="use-cases" tabindex="-1">Use cases <a class="header-anchor" href="#use-cases" aria-label="Permalink to &quot;Use cases&quot;">​</a></h2><ul><li><strong>Render an unpublished storefront page</strong> — the array is ready to draw in order, with each section&#39;s content already resolved for the locale.</li><li><strong>Show a merchant what publishing would change</strong> — compare <code>hasDraft</code> per section against the published <a href="/api/rest-api/admin/appearance/sections/list.html">List sections</a> response.</li></ul><h2 id="best-practices" tabindex="-1">Best practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best practices&quot;">​</a></h2><ul><li><strong>Sections staged off do not appear at all.</strong> The preview is what shoppers would see, so an off section is absent rather than present with <code>status: false</code> — do not use this endpoint to build the editor&#39;s list.</li><li><strong>A section with no staged edits is returned with its published values</strong>, so the preview is complete even when only one section was touched.</li></ul><h2 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Errors&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Status</th><th>When</th></tr></thead><tbody><tr><td><code>404</code></td><td>Unknown theme code.</td></tr></tbody></table><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><p>Requires <code>appearance.sections</code>.</p>',19)]))}const m=t(s,[["render",o]]);export{u as __pageData,m as default};
